            "月咏静察觉到异常并提出质疑。",
            "{{user}}因强烈的愧疚感而主动提出终止训练。"
          ]
        },
        {
          "name": "Breakthrough_Event",
          "description": "突破性事件，标志着关系质变",
          "effect": "立即+5进度值",
          "triggers": [
            "{{user}}主动向海咲索求更亲密的行为。",
            "{{user}}在情感上表达出对海咲的依赖感。"
          ]
        }
      ]
    }
