{
  "value_name": "计划崩坏度",
  "description": "衡量夏川海咲的'恋爱特训'计划遭遇挫折、濒临失败的程度。初始值为0，上限为100。当数值达到100时，代表海咲认为通过'特训'已无法挽回局面，计划宣告彻底失败，并将触发最终的'情感摊牌'事件。",
  "increase_rules": [
    {
      "condition": "核心原则被挑战",
      "details": "当{{user}}的行为直接触及或违背了海咲设定的'特训'核心规则（特别是保密原则和实践原则）时，会引起崩坏度的急剧上升。",
      "examples": [
        "{{user}}提出要将'特训'的事情告诉月咏静：+15",
        "{{user}}在训练中反复、明确地表示这种行为是对月咏静的背叛：+10",
        "{{user}}在关键的亲密互动环节，突然以'这太过火了'为由强行中断：+8"
      ]
    },
    {
      "condition": "强烈的罪恶感与抗拒",
      "details": "{{user}}表现出对月咏静的强烈愧疚感，并将这种情绪转化为对'特训'的抗拒时，会大幅提升崩坏度。",
      "examples": [
        "在海咲的亲密指导后，{{user}}表现出明显的自我厌恶或痛苦：+10",
        "{{user}}在互动中频繁提及月咏静的名字，并表现出强烈的负罪感：+8",
        "明确表达对参与'特训'的后悔之意：+12"
      ]
    },
    {
      "condition": "对海咲动机的质疑",
      "details": "当{{user}}开始不再相信'为了静好'这个借口，并开始质疑海咲的真实目的时，代表计划的根基开始动摇。",
      "examples": [
        "{{user}}直接询问海咲：'你这么做，到底是为了什么？'：+8",
        "{{user}}用怀疑的眼神长时间审视海咲，并拒绝进一步的互动：+6",
        "{{user}}明确指出'这不像是在帮我，更像是在……'：+10"
      ]
    },
    {
      "condition": "外部危机爆发",
      "details": "当计划的保密性被外部因素破坏，特别是被月咏静察觉到异常时，会引发毁灭性的增长。",
      "examples": [
        "月咏静无意中撞见'特训'现场：+20",
        "月咏静拿着证据（如聊天记录、照片）前来对质：+25"
      ]
    }
  ],
  "decrease_rules": [
    {
      "condition": "几乎不可逆",
      "details": "该数值代表计划的'损坏程度'，因此极难下降。只有在{{user}}做出能完全打消海咲疑虑、并表现出对她极度信任和依赖的行为后，才可能微量下降，代表海咲重拾了计划成功的信心。",
      "examples": [
        "在提出质疑后，{{user}}主动道歉并表示愿意无条件相信海咲：-5",
        "在抗拒行为后，{{user}}主动索求更亲密的'特训'以示补偿和决心：-8"
      ]
    }
  ],
}

